// BLD-12/13: equipo, sugerencia y AE2 (si js/bld-gear.js está cargado).
function gearHTML(b, code) {
  var G = root.GNBldGear;
  if (!G || !code) return '';
  if (!st.gear) st.gear = G.fresh();
  return G.panelHTML(st.gear, (b.weapons || []).map(function (w) { return C().WEAPONS[w]; }).filter(Boolean), code);
}
function onGear(ctx, e) {
  var G = root.GNBldGear;
  if (!G || !st.gear || !e.target || !e.target.closest || !e.target.closest('[data-gear],[data-gear-box]')) return false;
  var code = '';
  try { code = C().encode(st.build); } catch (_) {}
  if (G.onEvent(e, st.gear, code, function () { paint(ctx); })) paint(ctx, e.target.id || '');
  return true;
}

if (s) { e.preventDefault(); e.stopPropagation(); return saveFromEditor(st.ctx); }
if (e.target && e.target.closest && e.target.closest('[data-gear]')) return onGear(st.ctx, e);
onClick(st.ctx, e);

test('BLD-12/13: con bld-gear cargado, la ficha suma el panel de equipo y un AE2 válido', () => {
  globalThis.GNBldAe2 = require('../js/bld-ae2.js');
  globalThis.GNBldGear = require('../js/bld-gear.js');
  const st = E._state;
  st.gear = null;
  st.build.weapons = [50];
  const h = P.viewHTML();
  assert.match(h, /Equipo y código AE2/);
  const ae2 = (h.match(/<code>(AE2:[^<]+)<\/code>/) || [])[1];
  assert.ok(ae2, 'hay código AE2');
  const d = GNBldAe2.decode(ae2);
  assert.equal(d.code, C.encode(st.build));
  assert.equal(d.gear.WeaponA1.weaponType, 'Greatsword');
  assert.equal(d.gear.Helm.statId, 1077, 'poder en PvE: Berserker');
  delete globalThis.GNBldGear; delete globalThis.GNBldAe2;
});
